(function (root) {
  'use strict';

  const STEPS = Object.freeze(['Goals and Constraints','System Components','Data Flow','AI Workflow','APIs and Integrations','Privacy and Security','Deployment','Reliability and Monitoring','Architecture Decisions','Final Review']);
  const STATUSES = Object.freeze(['Draft','Needs More Detail','Ready for Review','Under Review','Changes Requested','Approved','Archived']);
  const COMPONENT_TYPES = Object.freeze(['User Interface','Mobile Interface','Backend Server','API','Database','File Storage','Authentication','AI Model','Prompt Builder','Source Retrieval','Vector Search','Privacy Filter','Content Filter','Output Validator','Human Review','Notification Service','Analytics','External Service','Teacher Dashboard','Admin Dashboard']);
  const TEMPLATES = Object.freeze([
    {id:'learning',icon:'✦',title:'AI Learning Assistant',description:'A guided learning tool with privacy, policy, validation, and human review.',components:['User Interface','Authentication','Privacy Filter','Prompt Builder','AI Model','Output Validator','Human Review']},
    {id:'research',icon:'⌕',title:'Research and Source Tool',description:'A research workflow that retrieves, compares, and verifies sources.',components:['User Interface','Source Retrieval','Database','AI Model','Output Validator','Human Review']},
    {id:'accessibility',icon:'Aa',title:'Accessibility and Language Tool',description:'A multilingual, assistive workflow with low-bandwidth fallbacks.',components:['User Interface','Translation Service','Text-to-Speech','Speech-to-Text','Human Review']},
    {id:'community',icon:'◎',title:'Community Resource Platform',description:'A searchable community service with authorized updates and escalation.',components:['User Interface','Authentication','Backend Server','Database','Source Retrieval','Admin Dashboard']},
    {id:'scratch',icon:'＋',title:'Start from Scratch',description:'Build a custom architecture one reviewed component at a time.',components:[]}
  ]);
  const AI_STAGES = Object.freeze(['User Input','Privacy Redaction','Assignment Policy Check','Prompt Builder','AI Model','Source Retrieval','Safety Check','Output Validation','Human or Student Review','Final Response']);
  const SECURITY_CHECKS = Object.freeze(['Server-side authorization','Private-data exposure','Secret storage','Uploaded-file validation','Sensitive-action audit logs','Role permissions','External-service failures','User deletion controls']);
  const REVIEW_CHECK_LABELS = Object.freeze(['Unconnected components','Server-side authorization','Sensitive data','Missing human review','Single points of failure','Missing backups','Integrations without fallbacks','Missing accessibility','Missing low-bandwidth support','Problem Scope requirements not represented','System Card conflicts']);
  const DATA_MODELS = Object.freeze({
    ProjectArchitecture:['id','projectId','userId','title','description','architectureGoal','status','currentStep','version','openIssueCount','submittedAt','approvedAt','createdAt','updatedAt'],
    ArchitectureComponent:['id','architectureId','componentType','name','purpose','technology','inputs','outputs','dependencies','responsibleUserId','dataSensitivity','limitations','failureBehaviour','fallbackBehaviour','positionX','positionY','displayOrder','createdAt','updatedAt'],
    ArchitectureConnection:['id','architectureId','sourceComponentId','destinationComponentId','label','dataType','transferMode','containsPersonalData','protectionMethod','retentionPolicy','failureBehaviour','createdAt','updatedAt'],
    ArchitectureIntegration:['id','architectureId','serviceName','purpose','dataSent','dataReceived','authenticationReference','rateLimitNotes','costNotes','privacyConcerns','failureBehaviour','fallbackBehaviour','createdAt','updatedAt'],
    ArchitectureDecision:['id','architectureId','title','problem','optionsConsidered','selectedOption','reason','advantages','disadvantages','risks','reviewDate','createdBy','createdAt','updatedAt'],
    ArchitectureIssue:['id','architectureId','componentId','issueType','description','whyItMatters','suggestedAction','status','resolvedAt','createdAt','updatedAt'],
    ArchitectureReview:['id','architectureId','reviewerId','status','feedback','requestedChanges','reviewedAt','createdAt','updatedAt'],
    ArchitectureVersion:['id','architectureId','version','changeSummary','componentsChanged','connectionsChanged','securityChanges','createdBy','createdAt']
  });
  const now=()=>new Date().toISOString(), uid=p=>`${p}-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;
  const esc=value=>String(value==null?'':value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const accountId=()=>root.localStorage?.getItem('studyspark_session_v1')||'signed-out';
  const storageKey=()=>`studyspark_project_architectures_v1:${accountId()}`;
  let activeId=null, step=0, message='', loadError=false, editingComponentId=null, sharePreview=false, zoom=1;
  const undoStacks=new Map(), redoStacks=new Map();

  function blankArchitecture(seed={}) {
    const stamp=now();
    return {id:uid('architecture'),projectId:seed.projectId||uid('project'),userId:accountId(),title:seed.title||'',projectName:seed.projectName||'Selected Project',description:seed.description||'',architectureGoal:'',problemAddressed:seed.problemAddressed||'',intendedUsers:seed.intendedUsers||'',requiredCapabilities:seed.requiredCapabilities||'',accessibilityRequirements:seed.accessibilityRequirements||'',languageRequirements:seed.languageRequirements||'',privacyRequirements:seed.privacyRequirements||'',lowBandwidthRequirements:seed.lowBandwidthRequirements||'',humanReviewRequirements:seed.humanReviewRequirements||'',budgetLimits:'',technicalConstraints:'',requiredRequirements:'',preferredRequirements:'',outOfScope:'',components:seed.components||[],connections:[],aiWorkflow:Object.fromEntries(AI_STAGES.map(name=>[name,{purpose:'',input:'',output:'',failure:'',validation:'',humanEscalation:''}])),modelProvider:'',promptTemplates:'',retrievalDesign:'',sourceRules:'',confidenceHandling:'',assumptions:'',finalAnswerRestrictions:'',contentModeration:'',aiHumanReview:'',integrations:[],authentication:'',roleAuthorization:'',dataAccess:'',encryption:'',dataMinimization:'',consent:'',retention:'',deletion:'',auditRecords:'',fileValidation:'',securityBoundaries:'',securityChecks:Object.fromEntries(SECURITY_CHECKS.map(name=>[name,'Not Reviewed'])),development:'',testingEnvironment:'',staging:'',production:'',hosting:'',frontendDeployment:'',backendDeployment:'',database:'',fileStorage:'',environmentVariables:'',databaseMigrations:'',backups:'',domain:'',https:'',deploymentWorkflow:'',rollback:'',monitoring:{errorLogging:'',performance:'',healthChecks:'',securityAlerts:'',aiFailures:'',sourceFailures:'',backupMonitoring:'',usageMetrics:''},failures:[],decisions:[],issues:[],reviews:[],versions:[],knownLimitations:'',openQuestions:'',status:'Draft',currentStep:0,version:'0.1',openIssueCount:0,submittedAt:null,approvedAt:null,createdAt:stamp,updatedAt:stamp,privateByDefault:true,importedSources:[],importsReviewed:false,languageMode:'English'};
  }
  function readAll(){try{const data=JSON.parse(root.localStorage?.getItem(storageKey())||'[]');loadError=false;return Array.isArray(data)?data.filter(item=>item&&item.userId===accountId()):[]}catch(_){loadError=true;return[]}}
  function writeAll(items){try{root.localStorage?.setItem(storageKey(),JSON.stringify(items));loadError=false;return true}catch(_){loadError=true;return false}}
  function getArchitecture(){return readAll().find(item=>item.id===activeId)||null}
  function saveArchitecture(architecture,notice='Draft saved'){const items=readAll(),index=items.findIndex(item=>item.id===architecture.id);architecture.userId=accountId();architecture.updatedAt=now();architecture.currentStep=Math.max(architecture.currentStep||0,step);architecture.openIssueCount=(architecture.issues||[]).filter(issue=>issue.status==='Open').length;if(index>=0)items[index]=architecture;else items.unshift(architecture);const saved=writeAll(items);message=saved?notice:'Unable to save architecture';return saved}
  function pushUndo(architecture){const stack=undoStacks.get(architecture.id)||[];stack.push(JSON.stringify(architecture));if(stack.length>30)stack.shift();undoStacks.set(architecture.id,stack);redoStacks.set(architecture.id,[])}
  function createArchitecture(seed={}){const architecture=blankArchitecture(seed);architecture.components.forEach(component=>{component.architectureId=architecture.id});activeId=architecture.id;step=0;editingComponentId=null;sharePreview=false;saveArchitecture(architecture,'Private architecture draft created');render()}
  function importRecord(kind){let seed={},sourceName=kind==='scope'?'Problem Scope':'System Card';try{if(kind==='scope'){const records=JSON.parse(root.localStorage?.getItem(`studyspark_problem_scopes_v1:${accountId()}`)||'[]'),scope=Array.isArray(records)?records[0]:null;if(scope)seed={projectId:scope.projectId,projectName:scope.title,title:`${scope.title||'Project'} Architecture`,problemAddressed:scope.problemStatement||scope.initialIdea,intendedUsers:scope.targetUsers,accessibilityRequirements:scope.accessibilityNeeds,languageRequirements:scope.languages,privacyRequirements:scope.constraints,lowBandwidthRequirements:scope.technologyLimits,humanReviewRequirements:scope.risks?.map(x=>x.humanOversight).filter(Boolean).join('; '),requiredRequirements:scope.inScope,outOfScope:scope.outOfScope}}else{const records=JSON.parse(root.localStorage?.getItem(`studyspark_system_cards_v1:${accountId()}`)||'[]'),card=Array.isArray(records)?records[0]:null;if(card)seed={projectId:card.projectId,projectName:card.projectName,title:`${card.systemName||'Project'} Architecture`,description:card.shortDescription,problemAddressed:card.problemAddressed,intendedUsers:card.primaryUsers,requiredCapabilities:card.capabilities,accessibilityRequirements:card.accessibilityNeeds,languageRequirements:card.languages,privacyRequirements:card.privacyChecks,humanReviewRequirements:card.accountablePerson,outOfScope:card.unsupportedUses}}}catch(_){}createArchitecture(seed.title?seed:{title:`Imported ${sourceName} Architecture`,projectName:'Selected Project',description:'Review imported fields before saving.'});const architecture=getArchitecture();architecture.importedSources.push(sourceName);architecture.importsReviewed=false;saveArchitecture(architecture,`${sourceName} imported. Review every field before saving.`);render()}
  function fromTemplate(template){const components=template.components.map((type,index)=>({id:uid('component'),architectureId:'pending',componentType:COMPONENT_TYPES.includes(type)?type:'External Service',name:type,purpose:'Review and describe this suggested component.',technology:'Not selected',inputs:'',outputs:'',dependencies:'',responsibleUserId:accountId(),dataSensitivity:'Unknown',status:'Planned',limitations:'',failureBehaviour:'Show a clear error and stop safely.',fallbackBehaviour:'Use a reviewed non-AI or human fallback.',positionX:index%3,positionY:Math.floor(index/3),displayOrder:index+1,group:'',createdAt:now(),updatedAt:now()}));createArchitecture({title:template.id==='scratch'?'':template.title,projectName:'Selected Project',description:template.description,components})}

  const field=(label,name,value,type='textarea',help='')=>`<label>${label}${type==='input'?`<input data-ar-field="${name}" value="${esc(value)}">`:`<textarea data-ar-field="${name}">${esc(value)}</textarea>`}${help?`<small>${help}</small>`:''}</label>`;
  const select=(label,name,value,options)=>`<label>${label}<select data-ar-field="${name}">${options.map(option=>`<option ${option===value?'selected':''}>${option}</option>`).join('')}</select></label>`;
  const val=id=>root.document.getElementById(id)?.value?.trim()||'';
  const optionsForComponents=(architecture,selected='')=>architecture.components.map(component=>`<option value="${component.id}" ${component.id===selected?'selected':''}>${esc(component.name)}</option>`).join('');
  function addRecord(collection,record,notice){const architecture=sync(getArchitecture());if(!architecture)return;pushUndo(architecture);architecture[collection].push({id:uid(collection),architectureId:architecture.id,createdAt:now(),updatedAt:now(),...record});saveArchitecture(architecture,notice);render()}

  function header(){return root.ProjectToolHeader.render({pageClass:'ar-hero',titleId:'project-architecture-title',backAttributes:{'data-ar-action':'projects'},backLabel:'Return to Projects',mainClass:'ar-hero-content',iconClass:'ar-hero-icon',icon:'⌘',eyebrowClass:'ar-kicker ar-hero-eyebrow',eyebrow:'RESPONSIBLE PROJECT DESIGN',titleClass:'ar-hero-title',title:'Project Architecture',descriptionClass:'ar-hero-description',description:'Design how your project’s interface, AI services, data, security, human review, and external tools work together.',projectContext:{className:'ar-project ar-hero-project',ariaLabel:'Selected project',label:'Selected Project',projectName:readAll()[0]?.projectName||'Choose or create a project',buttonAttributes:{'data-ar-action':'projects'}},guidanceClass:'ar-reminder ar-hero-reminder',guidance:'Good architecture explains not only how the system works, but also what happens when a component fails.',actionsClass:'ar-hero-actions',actionsLabel:'Project Architecture actions',actions:[{label:'Build My Architecture',variant:'primary',attributes:{'data-ar-action':'start'}},{label:'Continue Draft',variant:'secondary',attributes:{'data-ar-action':'continue'}},{label:'Import from Problem Scope',variant:'secondary',attributes:{'data-ar-action':'import-scope'}},{label:'Import from System Card',variant:'secondary',attributes:{'data-ar-action':'import-card'}},{label:'View an Example',variant:'tertiary',attributes:{'data-ar-action':'example'}}]})}
  function summary(items){if(!items.length)return'';const architecture=items[0];return `<section class="ar-section" aria-labelledby="ar-summary"><div class="ar-section-head"><div><span class="ar-kicker">CURRENT ARCHITECTURE</span><h2 id="ar-summary">Architecture Overview</h2></div><span class="ar-status"><span aria-hidden="true">●</span> ${esc(architecture.status)}</span></div><div class="ar-summary-grid"><article><span aria-hidden="true">◔</span><h3>Architecture Completion</h3><strong>${Math.min((architecture.currentStep||0)+1,10)} of 10 steps</strong></article><article><span aria-hidden="true">▦</span><h3>Components</h3><strong>${architecture.components.length}</strong></article><article><span aria-hidden="true">△</span><h3>Open Architecture Issues</h3><strong>${architecture.openIssueCount||0}</strong></article><article><span aria-hidden="true">↻</span><h3>Last Updated</h3><strong>${new Date(architecture.updatedAt).toLocaleDateString()}</strong></article></div></section>`}
  function templates(){return `<section class="ar-section" aria-labelledby="ar-templates"><div class="ar-section-head"><div><span class="ar-kicker">QUICK START</span><h2 id="ar-templates">Architecture Templates</h2><p>Suggested components are editable. A template never overwrites a saved architecture.</p></div></div><div class="ar-template-grid">${TEMPLATES.map(template=>`<article><span aria-hidden="true">${template.icon}</span><h3>${template.title}</h3><p>${template.description}</p><small><strong>Suggested components:</strong> ${template.components.length?template.components.join(', '):'None — start with your own design.'}</small><button class="btn btn-secondary" data-ar-template="${template.id}" type="button">Start</button></article>`).join('')}</div></section>`}
  function emptyOrHistory(items){if(!items.length)return `<section class="ar-empty" aria-labelledby="ar-empty-title"><span aria-hidden="true">⌘</span><h2 id="ar-empty-title">Design how your project will work before building every feature.</h2><p>Add the interface, services, AI workflow, data storage, security controls, and human-review steps.</p><div><button class="btn btn-primary" data-ar-action="start" type="button">Build My First Architecture</button><button class="btn btn-secondary" data-ar-action="import-card" type="button">Import from System Card</button><button class="btn btn-secondary" data-ar-action="templates" type="button">Use an Architecture Template</button><button class="btn btn-quiet" data-ar-action="example" type="button">View an Example</button></div></section>`;return `<section class="ar-section" aria-labelledby="ar-history"><div class="ar-section-head"><div><span class="ar-kicker">PRIVATE HISTORY</span><h2 id="ar-history">Architecture History</h2></div></div><div class="ar-history-grid">${items.map(item=>`<article><div><span class="ar-status"><span aria-hidden="true">●</span> ${esc(item.status)}</span><h3>${esc(item.title||'Untitled Architecture')}</h3><p>${esc(item.projectName)} · Version ${esc(item.version)}</p><small>${item.components.length} components · ${item.connections.length} connections</small></div><div class="ar-card-actions"><button class="btn btn-primary" data-ar-open="${item.id}" type="button">Continue Draft</button><button class="btn btn-secondary" data-ar-action="duplicate-architecture" data-id="${item.id}" type="button">Duplicate</button><button class="btn btn-quiet" data-ar-action="export" data-id="${item.id}" type="button">Export</button><button class="btn btn-danger" data-ar-action="delete-architecture" data-id="${item.id}" type="button">Delete Draft</button></div></article>`).join('')}</div></section>`}
  function overview(){const items=readAll();return `${header()}${message?`<p class="ar-live" role="status">${esc(message)}</p>`:''}${summary(items)}${templates()}${emptyOrHistory(items)}`}

  function stepGoals(a){return `<div class="ar-form-grid">${field('Architecture title','title',a.title,'input')}${field('Selected project name','projectName',a.projectName,'input')}${field('Architecture goal','architectureGoal',a.architectureGoal)}${field('Problem being addressed','problemAddressed',a.problemAddressed)}${field('Intended users','intendedUsers',a.intendedUsers)}${field('Required capabilities','requiredCapabilities',a.requiredCapabilities)}${field('Accessibility requirements','accessibilityRequirements',a.accessibilityRequirements)}${field('Language requirements','languageRequirements',a.languageRequirements)}${field('Privacy requirements','privacyRequirements',a.privacyRequirements)}${field('Low-bandwidth requirements','lowBandwidthRequirements',a.lowBandwidthRequirements)}${field('Human-review requirements','humanReviewRequirements',a.humanReviewRequirements)}${field('Budget or service limits','budgetLimits',a.budgetLimits)}${field('Technical constraints','technicalConstraints',a.technicalConstraints)}</div><div class="ar-requirements"><section><span class="ar-kicker">REQUIRED</span>${field('Required requirements','requiredRequirements',a.requiredRequirements)}</section><section><span class="ar-kicker">PREFERRED</span>${field('Preferred requirements','preferredRequirements',a.preferredRequirements)}</section><section><span class="ar-kicker">OUT OF SCOPE</span>${field('Out-of-scope features','outOfScope',a.outOfScope)}</section></div>${a.importedSources.length&&!a.importsReviewed?`<div class="ar-notice" role="note"><strong>Imported from ${esc(a.importedSources.join(' and '))}</strong><p>Review every imported requirement before it becomes part of this architecture.</p><button class="btn btn-secondary" data-ar-action="confirm-imports" type="button">I Reviewed the Imports</button></div>`:''}`}
  function componentEditor(a){const component=a.components.find(item=>item.id===editingComponentId)||{};return `<section class="ar-builder"><h3>${editingComponentId?'Edit Component':'Add Component'}</h3><div class="ar-form-grid compact"><label>Name<input id="ar-component-name" value="${esc(component.name||'')}"></label><label>Type<select id="ar-component-type">${COMPONENT_TYPES.map(type=>`<option ${type===component.componentType?'selected':''}>${type}</option>`).join('')}</select></label><label>Purpose<textarea id="ar-component-purpose">${esc(component.purpose||'')}</textarea></label><label>Technology or service<input id="ar-component-technology" value="${esc(component.technology||'')}"></label><label>Inputs<textarea id="ar-component-inputs">${esc(component.inputs||'')}</textarea></label><label>Outputs<textarea id="ar-component-outputs">${esc(component.outputs||'')}</textarea></label><label>Dependencies<textarea id="ar-component-dependencies">${esc(component.dependencies||'')}</textarea></label><label>Responsible person<input id="ar-component-responsible" value="${esc(component.responsibleUserId||'')}"></label><label>Data sensitivity<select id="ar-component-sensitivity"><option>None</option><option>Low</option><option>Personal</option><option>Sensitive</option><option>Unknown</option></select></label><label>Status<select id="ar-component-status"><option>Planned</option><option>Building</option><option>Implemented, not tested</option><option>Tested</option><option>Paused</option></select></label><label>Limitations<textarea id="ar-component-limitations">${esc(component.limitations||'')}</textarea></label><label>Failure behaviour<textarea id="ar-component-failure">${esc(component.failureBehaviour||'')}</textarea></label><label>Fallback<textarea id="ar-component-fallback">${esc(component.fallbackBehaviour||'')}</textarea></label></div><div class="ar-inline-actions"><button class="btn btn-secondary" data-ar-action="save-component" type="button">${editingComponentId?'Save Component Changes':'Add Component'}</button>${editingComponentId?'<button class="btn btn-quiet" data-ar-action="cancel-component" type="button">Cancel Edit</button>':''}</div></section>`}
  function canvas(a){return `<section class="ar-canvas" style="--architecture-zoom:${zoom}" aria-labelledby="ar-canvas-title"><div class="ar-canvas-head"><div><span class="ar-kicker">ARCHITECTURE CANVAS</span><h3 id="ar-canvas-title">Components and connections</h3></div><div class="ar-canvas-tools"><button class="btn btn-quiet" data-ar-action="undo" type="button">Undo</button><button class="btn btn-quiet" data-ar-action="redo" type="button">Redo</button><button class="btn btn-quiet" data-ar-action="zoom-in" type="button" aria-label="Zoom in">＋</button><button class="btn btn-quiet" data-ar-action="zoom-out" type="button" aria-label="Zoom out">−</button><button class="btn btn-quiet" data-ar-action="fit" type="button">Fit to Screen</button></div></div><div class="ar-component-canvas">${a.components.length?a.components.map((component,index)=>`<article data-group="${esc(component.group||'')}"><span>${index+1}</span><h4>${esc(component.name)}</h4><p>${esc(component.componentType)}</p><small>${esc(component.purpose||'Purpose needed')}</small><div><button data-ar-action="edit-component" data-id="${component.id}" type="button">Edit</button><button data-ar-action="duplicate-component" data-id="${component.id}" type="button">Duplicate</button><button data-ar-action="move-up" data-id="${component.id}" type="button">Move Up</button><button data-ar-action="move-down" data-id="${component.id}" type="button">Move Down</button><button data-ar-action="group-component" data-id="${component.id}" type="button">Group</button><button data-ar-action="delete-component" data-id="${component.id}" type="button">Delete</button></div></article>`).join(''):'<p>No components yet. Add the first component with the form above.</p>'}</div><div class="ar-connection-list"><h4>Accessible connection list</h4>${a.connections.length?`<ol>${a.connections.map(connection=>{const from=a.components.find(x=>x.id===connection.sourceComponentId)?.name||'Unknown',to=a.components.find(x=>x.id===connection.destinationComponentId)?.name||'Unknown';return `<li><strong>${esc(from)} → ${esc(to)}</strong>: ${esc(connection.label||connection.dataType||'Connection')}</li>`}).join('')}</ol>`:'<p>No connections yet.</p>'}</div></section>`}
  function stepComponents(a){return `${componentEditor(a)}${canvas(a)}`}
  function stepData(a){return `<div class="ar-flow-labels" aria-label="Suggested data labels">${['Student Prompt','User Preferences','Uploaded Document','Verified Sources','AI Response','Session Record','Anonymous Analytics'].map(label=>`<span>${label}</span>`).join('')}</div><section class="ar-builder"><h3>Add Data Flow Connection</h3>${a.components.length<2?'<p class="ar-notice">Add at least two components before connecting a data flow.</p>':`<div class="ar-form-grid compact"><label>Data name<input id="ar-flow-name"></label><label>Source component<select id="ar-flow-source">${optionsForComponents(a)}</select></label><label>Destination component<select id="ar-flow-destination">${optionsForComponents(a)}</select></label><label>Direction<select id="ar-flow-direction"><option>One way</option><option>Two way</option></select></label><label>Transfer mode<select id="ar-flow-mode"><option>Synchronous</option><option>Asynchronous</option></select></label><label>Personal information involved<select id="ar-flow-personal"><option>No</option><option>Possibly</option><option>Yes</option><option>Unknown</option></select></label><label>Storage<textarea id="ar-flow-storage"></textarea></label><label>Retention<textarea id="ar-flow-retention"></textarea></label><label>Protection method<textarea id="ar-flow-protection"></textarea></label><label>Failure behaviour<textarea id="ar-flow-failure"></textarea></label></div><button class="btn btn-secondary" data-ar-action="add-connection" type="button">Connect Components</button>`}</section>${a.connections.some(x=>['Yes','Possibly','Unknown'].includes(x.containsPersonalData)&&!x.protectionMethod)?'<p class="ar-warning" role="alert">Sensitive or uncertain data has no documented protection method.</p>':''}${canvas(a)}`}
  function stepAI(a){return `<div class="ar-ai-pipeline" aria-label="AI workflow">${AI_STAGES.map((name,index)=>`<span>${esc(name)}</span>${index<AI_STAGES.length-1?'<b aria-hidden="true">→</b>':''}`).join('')}</div><ol class="ar-mobile-pipeline">${AI_STAGES.map(name=>`<li>${name}</li>`).join('')}</ol><div class="ar-ai-stages">${AI_STAGES.map((name,index)=>{const stage=a.aiWorkflow[name];return `<details ${index===0?'open':''}><summary>${index+1}. ${name}</summary><div class="ar-form-grid compact">${field('Purpose',`ai_${index}_purpose`,stage.purpose)}${field('Input',`ai_${index}_input`,stage.input)}${field('Output',`ai_${index}_output`,stage.output)}${field('Possible failure',`ai_${index}_failure`,stage.failure)}${field('Validation',`ai_${index}_validation`,stage.validation)}${field('Human escalation',`ai_${index}_humanEscalation`,stage.humanEscalation)}</div></details>`}).join('')}</div><div class="ar-form-grid">${field('Model or provider','modelProvider',a.modelProvider)}${field('Prompt templates','promptTemplates',a.promptTemplates)}${field('Retrieval','retrievalDesign',a.retrievalDesign)}${field('Source rules','sourceRules',a.sourceRules)}${field('Confidence handling','confidenceHandling',a.confidenceHandling)}${field('Assumptions','assumptions',a.assumptions)}${field('Final-answer restrictions','finalAnswerRestrictions',a.finalAnswerRestrictions)}${field('Content moderation','contentModeration',a.contentModeration)}${field('Human review','aiHumanReview',a.aiHumanReview)}</div>`}
  function stepIntegrations(a){return `<p class="ar-guidance">Never store actual API keys, passwords, or access tokens. Store only an environment-variable name or secret reference.</p><div class="ar-form-grid compact"><label>Integration type<select id="ar-integration-type"><option>AI provider</option><option>Translation</option><option>Speech-to-text</option><option>Text-to-speech</option><option>Email</option><option>Calendar</option><option>File storage</option><option>Learning-management system</option><option>School system</option><option>Analytics</option></select></label><label>Name<input id="ar-integration-name"></label><label>Purpose<textarea id="ar-integration-purpose"></textarea></label><label>Data sent<textarea id="ar-integration-sent"></textarea></label><label>Data received<textarea id="ar-integration-received"></textarea></label><label>Authentication reference<input id="ar-integration-auth" placeholder="Example: AI_PROVIDER_API_KEY"></label><label>Rate limit<textarea id="ar-integration-rate"></textarea></label><label>Cost concern<textarea id="ar-integration-cost"></textarea></label><label>Privacy concern<textarea id="ar-integration-privacy"></textarea></label><label>Failure behaviour<textarea id="ar-integration-failure"></textarea></label><label>Fallback<textarea id="ar-integration-fallback"></textarea></label></div><button class="btn btn-secondary" data-ar-action="add-integration" type="button">Add Integration</button>${recordList(a.integrations,'Integrations','serviceName','purpose')}`}
  function stepSecurity(a){return `<div class="ar-form-grid">${field('Authentication','authentication',a.authentication)}${field('Role-based authorization','roleAuthorization',a.roleAuthorization)}${field('Data access','dataAccess',a.dataAccess)}${field('Encryption','encryption',a.encryption)}${field('Data minimization','dataMinimization',a.dataMinimization)}${field('Consent','consent',a.consent)}${field('Retention','retention',a.retention)}${field('Deletion','deletion',a.deletion)}${field('Audit records','auditRecords',a.auditRecords)}${field('File validation','fileValidation',a.fileValidation)}${field('Security boundaries','securityBoundaries',a.securityBoundaries)}</div><section class="ar-checks"><h3>Architecture Security Checks</h3>${SECURITY_CHECKS.map(name=>`<label><span>${name}</span><select data-ar-security="${esc(name)}"><option ${a.securityChecks[name]==='Not Reviewed'?'selected':''}>Not Reviewed</option><option ${a.securityChecks[name]==='Planned'?'selected':''}>Planned</option><option ${a.securityChecks[name]==='Issue Found'?'selected':''}>Issue Found</option><option ${a.securityChecks[name]==='Protected'?'selected':''}>Protected</option><option ${a.securityChecks[name]==='Needs Human Review'?'selected':''}>Needs Human Review</option></select></label>`).join('')}</section>`}
  function stepDeployment(a){return `<div class="ar-deploy-flow" aria-label="Deployment workflow"><span>Code Change</span><b>→</b><span>Automated Tests</span><b>→</b><span>Preview Deployment</span><b>→</b><span>Review</span><b>→</b><span>Production</span><b>→</b><span>Monitoring</span><b>→</b><span>Rollback if Needed</span></div><div class="ar-form-grid">${field('Development','development',a.development)}${field('Testing','testingEnvironment',a.testingEnvironment)}${field('Staging','staging',a.staging)}${field('Production','production',a.production)}${field('Hosting','hosting',a.hosting)}${field('Frontend deployment','frontendDeployment',a.frontendDeployment)}${field('Backend deployment','backendDeployment',a.backendDeployment)}${field('Database','database',a.database)}${field('File storage','fileStorage',a.fileStorage)}${field('Environment variables','environmentVariables',a.environmentVariables,'textarea','List names only. Never enter secret values.')}${field('Database migrations','databaseMigrations',a.databaseMigrations)}${field('Backups','backups',a.backups)}${field('Domain','domain',a.domain,'input')}${field('HTTPS','https',a.https)}${field('Deployment workflow','deploymentWorkflow',a.deploymentWorkflow)}${field('Rollback','rollback',a.rollback)}</div>`}
  function stepReliability(a){return `<div class="ar-form-grid">${field('Error logging','monitor_errorLogging',a.monitoring.errorLogging)}${field('Performance monitoring','monitor_performance',a.monitoring.performance)}${field('Health checks','monitor_healthChecks',a.monitoring.healthChecks)}${field('Security alerts','monitor_securityAlerts',a.monitoring.securityAlerts)}${field('AI failures','monitor_aiFailures',a.monitoring.aiFailures)}${field('Source-verification failures','monitor_sourceFailures',a.monitoring.sourceFailures)}${field('Backup monitoring','monitor_backupMonitoring',a.monitoring.backupMonitoring)}${field('Usage metrics','monitor_usageMetrics',a.monitoring.usageMetrics)}</div><section class="ar-builder"><h3>Major Failure and Recovery</h3><div class="ar-form-grid compact"><label>Failure<textarea id="ar-failure-name"></textarea></label><label>Detection<textarea id="ar-failure-detection"></textarea></label><label>User message<textarea id="ar-failure-message"></textarea></label><label>Retry<textarea id="ar-failure-retry"></textarea></label><label>Fallback<textarea id="ar-failure-fallback"></textarea></label><label>Responsible person<input id="ar-failure-responsible"></label><label>Recovery process<textarea id="ar-failure-recovery"></textarea></label></div><button class="btn btn-secondary" data-ar-action="add-failure" type="button">Add Failure Plan</button></section>${recordList(a.failures,'Failure plans','failure','userMessage')}`}
  function stepDecisions(a){return `<section class="ar-builder"><h3>Architecture Decision Log</h3><div class="ar-form-grid compact"><label>Decision title<input id="ar-decision-title"></label><label>Problem<textarea id="ar-decision-problem"></textarea></label><label>Options<textarea id="ar-decision-options"></textarea></label><label>Selected option<textarea id="ar-decision-selected"></textarea></label><label>Reason<textarea id="ar-decision-reason"></textarea></label><label>Advantages<textarea id="ar-decision-advantages"></textarea></label><label>Disadvantages<textarea id="ar-decision-disadvantages"></textarea></label><label>Risks<textarea id="ar-decision-risks"></textarea></label><label>Decision-maker<input id="ar-decision-maker"></label><label>Date<input id="ar-decision-date" type="date"></label><label>Review date<input id="ar-decision-review" type="date"></label></div><button class="btn btn-secondary" data-ar-action="add-decision" type="button">Add Decision</button></section>${recordList(a.decisions,'Architecture decisions','title','reason')}`}
  function recordList(items,kind,title='name',detail='description'){return items.length?`<div class="ar-record-list">${items.map(item=>`<article><h3>${esc(item[title]||kind)}</h3><p>${esc(item[detail]||'Details saved')}</p><small>${esc(item.status||item.integrationType||item.createdBy||'Draft')}</small></article>`).join('')}</div>`:`<p class="ar-inline-empty">No ${kind.toLowerCase()} added yet.</p>`}
  function reviewIssues(a){const issues=[];const add=(type,description,why,suggestion,componentId=null)=>issues.push({id:uid('issue'),architectureId:a.id,componentId,issueType:type,description,whyItMatters:why,suggestedAction:suggestion,status:'Open',resolvedAt:null,createdAt:now(),updatedAt:now()});if(!a.components.length)add('MISSING_COMPONENTS','No system components are documented.','A diagram cannot explain the system without components.','Add the user interface, services, storage, validation, and human review.');a.components.filter(c=>!c.purpose).forEach(c=>add('MISSING_PURPOSE',`${c.name} has no purpose.`, 'People cannot evaluate why the component exists.','Add a specific purpose.',c.id));if(a.components.length>1&&a.connections.length===0)add('UNCONNECTED_COMPONENTS','Unconnected components were found.','Data and control flow remain unclear.','Add reviewed connections between components.');if(!a.authentication)add('MISSING_AUTHENTICATION','Authentication is not documented.','Private project data may be exposed.','Document how users sign in.');if(!a.roleAuthorization)add('MISSING_AUTHORIZATION','Server-side authorization is not documented.','Signed-in users may access records they do not own.','Add role and project-membership checks.');if(a.connections.some(c=>['Yes','Possibly','Unknown'].includes(c.containsPersonalData)&&!c.protectionMethod))add('UNPROTECTED_DATA','Sensitive data has no documented protection.','Personal information could cross a boundary without safeguards.','Add minimization, redaction, encryption, or block the transfer.');if(a.components.some(c=>c.componentType==='AI Model')&&!a.aiWorkflow['Output Validation'].validation)add('AI_OUTPUT_UNVERIFIED','AI output has no documented validation.','Unsupported output could reach users.','Add output validation and a failure path.');if(!a.humanReviewRequirements&&!a.aiHumanReview)add('MISSING_HUMAN_REVIEW','Missing human review.','AI cannot be accountable for important decisions.','Add a real reviewer with authority to correct or stop the system.');if(a.components.some(c=>!c.failureBehaviour))add('MISSING_FAILURE_BEHAVIOUR','One or more components have no failure behaviour.','A service failure could leave the page blank or unsafe.','Document a user message, retry, fallback, and owner.');if(a.components.length>2&&!a.failures.length)add('SINGLE_POINT_OF_FAILURE','Single points of failure have not been assessed.','One failed service could stop the complete workflow.','Document major failures, detection, recovery, and responsible people.');if(!a.backups)add('MISSING_BACKUPS','Missing backups.','Recovery may be impossible after data loss.','Add a backup and restoration plan.');if(a.integrations.some(i=>!i.fallbackBehaviour))add('INTEGRATION_NO_FALLBACK','Integrations without fallbacks were found.','External failures can block the workflow.','Add a bounded fallback or safe stop.');if(!a.accessibilityRequirements)add('MISSING_ACCESSIBILITY','Missing accessibility requirements.','Some users may be excluded.','Document keyboard, screen-reader, text, language, and media needs.');if(!a.lowBandwidthRequirements)add('MISSING_LOW_BANDWIDTH','Missing low-bandwidth support.','The project may fail for users with weak connections.','Add a text-only or offline fallback.');if(a.importedSources.includes('Problem Scope')&&!a.requiredRequirements)add('PROBLEM_SCOPE_GAP','Problem Scope requirements not represented.','The architecture may not implement the agreed project boundary.','Review the imported Problem Scope and connect each required capability to a component.');if(a.importedSources.includes('System Card')&&!a.importsReviewed)add('SYSTEM_CARD_CONFLICT','System Card conflicts may remain unresolved.','Imported responsibilities and limitations require student review.','Review the System Card import and resolve conflicts before submitting.');return issues}
  function finalRows(a){const front=a.components.filter(c=>/Interface|Dashboard/.test(c.componentType)).map(c=>c.name).join(', '),back=a.components.filter(c=>/Server|API/.test(c.componentType)).map(c=>c.name).join(', '),storage=a.components.filter(c=>/Database|Storage/.test(c.componentType)).map(c=>c.name).join(', ');return [['Project Name',a.projectName],['Architecture Goal',a.architectureGoal],['System Overview',a.description],['Frontend Components',front],['Backend Components',back],['Data Storage',storage],['AI Workflow',a.modelProvider||'No AI provider documented'],['External Integrations',a.integrations.map(x=>x.serviceName).join(', ')],['Data Flow',`${a.connections.length} documented connections`],['Privacy Controls',a.dataMinimization],['Security Controls',a.roleAuthorization],['Human Oversight',a.humanReviewRequirements||a.aiHumanReview],['Deployment Plan',a.deploymentWorkflow],['Monitoring',a.monitoring.healthChecks],['Failure and Fallback Plan',a.failures.map(x=>x.failure).join(', ')],['Architecture Decisions',a.decisions.map(x=>x.title).join(', ')],['Known Limitations',a.knownLimitations],['Open Questions',a.openQuestions],['Version',a.version],['Last Updated',new Date(a.updatedAt).toLocaleDateString()]]}
  function stepReview(a){return `<div class="ar-review-head"><button class="btn btn-primary" data-ar-action="review" type="button">Review My Architecture</button><p>This check identifies issues but never changes the architecture automatically.</p></div><section class="ar-checks" aria-labelledby="ar-review-checks"><h3 id="ar-review-checks">Review checks</h3><ul>${REVIEW_CHECK_LABELS.map(label=>`<li><span aria-hidden="true">✓</span>${label}</li>`).join('')}</ul></section>${a.issues.length?`<section class="ar-issues"><h3>Architecture Review Issues</h3>${a.issues.map(issue=>`<article><span class="ar-status"><span aria-hidden="true">△</span> ${esc(issue.status)}</span><h4>${esc(issue.description)}</h4><p><strong>Why it matters:</strong> ${esc(issue.whyItMatters)}</p><p><strong>Suggested improvement:</strong> ${esc(issue.suggestedAction)}</p><button class="btn btn-secondary" data-ar-action="resolve-issue" data-id="${issue.id}" type="button">Mark Addressed</button></article>`).join('')}</section>`:''}<article class="ar-final"><div><span class="ar-kicker">FINAL ARCHITECTURE SUMMARY</span><h2>${esc(a.title||'Untitled Architecture')}</h2><span class="ar-status"><span aria-hidden="true">●</span> ${esc(a.status)}</span></div><dl>${finalRows(a).map(([name,value])=>`<div><dt>${name}</dt><dd>${value?esc(value):'Not documented yet.'}</dd></div>`).join('')}</dl></article><div class="ar-form-grid">${field('Known limitations','knownLimitations',a.knownLimitations)}${field('Open questions','openQuestions',a.openQuestions)}</div>${sharePreview?'<section class="ar-share-preview" role="region" aria-label="Export preview"><h3>Export Preview</h3><p>Private technical notes, personal information, secret values, security details, and private AI conversations are excluded. Nothing has been shared.</p><button class="btn btn-secondary" data-ar-action="close-preview" type="button">Close Preview</button></section>':''}<div class="ar-final-actions"><button class="btn btn-secondary" data-ar-action="edit" type="button">Edit Architecture</button><button class="btn btn-secondary" data-ar-action="save" type="button">Save Draft</button><button class="btn btn-primary" data-ar-action="submit" type="button">Request Teacher Review</button><button class="btn btn-secondary" data-ar-action="preview" type="button">Export Diagram</button><button class="btn btn-secondary" data-ar-action="export-current" type="button">Export Report</button><button class="btn btn-primary" data-ar-action="prototype" type="button">Continue to Prototype</button></div><section class="ar-version-history"><h3>Version History and Review</h3>${a.versions.length?`<ol>${a.versions.map(version=>`<li><strong>Version ${esc(version.version)}</strong> · ${new Date(version.createdAt).toLocaleDateString()} · ${esc(version.createdBy)}<p>${esc(version.changeSummary)}</p><small>Components: ${esc(version.componentsChanged)} · Connections: ${esc(version.connectionsChanged)} · Security: ${esc(version.securityChanges)}</small></li>`).join('')}</ol>`:'<p>No preserved versions yet.</p>'}<button class="btn btn-secondary" data-ar-action="version" type="button">Preserve Current Version</button><button class="btn btn-quiet" data-ar-action="compare" type="button">Compare Versions</button><p>Human approval is required. AI cannot approve an architecture.</p></section>`}
  const renderStep=a=>[stepGoals,stepComponents,stepData,stepAI,stepIntegrations,stepSecurity,stepDeployment,stepReliability,stepDecisions,stepReview][step](a);
  function wizard(a){return `<header class="ar-workspace-head"><button class="study-page-back" data-ar-action="overview" type="button" aria-label="Return to Architecture overview"><span aria-hidden="true">←</span></button><div><span class="ar-kicker">PRIVATE PROJECT ARCHITECTURE</span><h1>Project Architecture</h1><p>${esc(a.projectName)} · ${esc(a.status)}</p></div><div class="ar-access-actions"><label>Description language<select data-ar-field="languageMode"><option ${a.languageMode==='English'?'selected':''}>English</option><option ${a.languageMode==='Bilingual'?'selected':''}>Bilingual</option></select></label><button class="btn btn-quiet" data-ar-action="listen" type="button">Listen</button><button class="btn btn-quiet" data-ar-action="speech" type="button">Speech-to-Text</button></div></header><nav class="ar-stepper" aria-label="Architecture steps"><ol>${STEPS.map((name,index)=>`<li ${index===step?'aria-current="step"':''}><button data-ar-step="${index}" type="button"><span>${index+1}</span>${name}</button></li>`).join('')}</ol></nav><section class="ar-wizard" aria-labelledby="ar-current-step"><div class="ar-progress"><div><span>Step ${step+1} of 10</span><strong id="ar-current-step">${STEPS[step]}</strong></div><progress max="10" value="${step+1}">${step+1} of 10</progress></div>${message?`<p class="ar-live" role="status">${esc(message)}</p>`:''}<div class="ar-step-content">${renderStep(a)}</div><footer class="ar-wizard-actions"><button class="btn btn-secondary" data-ar-action="save" type="button">Save Draft</button><button class="btn btn-quiet" data-ar-action="overview" type="button">Exit and Return Later</button><span></span><button class="btn btn-secondary" data-ar-action="back" type="button" ${step===0?'disabled':''}>Back</button><button class="btn btn-primary" data-ar-action="next" type="button">${step===9?'Review Architecture':'Continue'}</button></footer></section>`}

  function sync(a){if(!a)return a;root.document.querySelectorAll('#architectureContent [data-ar-field]').forEach(control=>a[control.dataset.arField]=control.value);root.document.querySelectorAll('#architectureContent [data-ar-security]').forEach(control=>a.securityChecks[control.dataset.arSecurity]=control.value);AI_STAGES.forEach((name,index)=>{const stage=a.aiWorkflow[name];['purpose','input','output','failure','validation','humanEscalation'].forEach(key=>{const value=a[`ai_${index}_${key}`];if(value!==undefined)stage[key]=value})});a.monitoring={errorLogging:a.monitor_errorLogging||a.monitoring.errorLogging,performance:a.monitor_performance||a.monitoring.performance,healthChecks:a.monitor_healthChecks||a.monitoring.healthChecks,securityAlerts:a.monitor_securityAlerts||a.monitoring.securityAlerts,aiFailures:a.monitor_aiFailures||a.monitoring.aiFailures,sourceFailures:a.monitor_sourceFailures||a.monitoring.sourceFailures,backupMonitoring:a.monitor_backupMonitoring||a.monitoring.backupMonitoring,usageMetrics:a.monitor_usageMetrics||a.monitoring.usageMetrics};return a}
  function saveComponent(){const a=sync(getArchitecture());pushUndo(a);const record={componentType:val('ar-component-type'),name:val('ar-component-name')||'Untitled Component',purpose:val('ar-component-purpose'),technology:val('ar-component-technology'),inputs:val('ar-component-inputs'),outputs:val('ar-component-outputs'),dependencies:val('ar-component-dependencies'),responsibleUserId:val('ar-component-responsible')||accountId(),dataSensitivity:val('ar-component-sensitivity'),status:val('ar-component-status'),limitations:val('ar-component-limitations'),failureBehaviour:val('ar-component-failure'),fallbackBehaviour:val('ar-component-fallback')};if(editingComponentId){const existing=a.components.find(x=>x.id===editingComponentId);Object.assign(existing,record,{updatedAt:now()});editingComponentId=null}else a.components.push({id:uid('component'),architectureId:a.id,displayOrder:a.components.length+1,positionX:a.components.length%3,positionY:Math.floor(a.components.length/3),group:'',createdAt:now(),updatedAt:now(),...record});saveArchitecture(a,'Component saved');render()}
  function preserveVersion(a){a.versions.push({id:uid('architecture-version'),architectureId:a.id,version:a.version,changeSummary:'Student preserved the current architecture.',componentsChanged:`${a.components.length} components documented`,connectionsChanged:`${a.connections.length} connections documented`,securityChanges:Object.entries(a.securityChecks).filter(([,status])=>status==='Protected').map(([name])=>name).join(', ')||'No protected checks recorded',createdBy:accountId(),createdAt:now()})}
  function exportArchitecture(a){const blob=new Blob([JSON.stringify(a,null,2)],{type:'application/json'}),link=root.document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`${(a.title||'project-architecture').replace(/[^a-z0-9]+/gi,'-').toLowerCase()}.json`;link.click();URL.revokeObjectURL(link.href)}
  function handle(action,id){const items=readAll();let a=getArchitecture();if(action==='retry')return retry();if(action==='projects')return root.showView?.('communityAIProject');if(action==='start')return createArchitecture();if(action==='continue'){const draft=items.find(x=>!['Approved','Archived'].includes(x.status))||items[0];return draft?(activeId=draft.id,step=Math.min(draft.currentStep||0,9),message='Draft restored',render()):createArchitecture()}if(action==='import-scope')return importRecord('scope');if(action==='import-card')return importRecord('card');if(action==='example')return fromTemplate(TEMPLATES[0]);if(action==='templates'){message='Choose a template above. Saved architectures will not be overwritten.';return render()}if(action==='overview'){if(a)saveArchitecture(sync(a),'Draft saved');activeId=null;editingComponentId=null;message='';return render()}if(action==='save'&&a){saveArchitecture(sync(a),'Draft saved');return render()}if(action==='back'&&a){saveArchitecture(sync(a),'Draft saved');step=Math.max(0,step-1);return render()}if(action==='next'&&a){saveArchitecture(sync(a),'Draft saved');step=Math.min(9,step+1);return render()}if(action==='edit'){step=0;return render()}if(action==='confirm-imports'&&a){a.importsReviewed=true;saveArchitecture(sync(a),'Imported requirements reviewed');return render()}if(action==='save-component')return saveComponent();if(action==='cancel-component'){editingComponentId=null;return render()}if(action==='edit-component'){editingComponentId=id;return render()}if(action==='duplicate-component'&&a){pushUndo(a);const original=a.components.find(x=>x.id===id);if(original)a.components.push({...JSON.parse(JSON.stringify(original)),id:uid('component'),name:`${original.name} — Copy`,displayOrder:a.components.length+1,createdAt:now(),updatedAt:now()});saveArchitecture(a,'Component duplicated');return render()}if(['move-up','move-down'].includes(action)&&a){pushUndo(a);const index=a.components.findIndex(x=>x.id===id),target=action==='move-up'?index-1:index+1;if(index>=0&&target>=0&&target<a.components.length)[a.components[index],a.components[target]]=[a.components[target],a.components[index]];a.components.forEach((component,i)=>component.displayOrder=i+1);saveArchitecture(a,'Component moved');return render()}if(action==='group-component'&&a){pushUndo(a);const component=a.components.find(x=>x.id===id);if(component)component.group=component.group?'':'Related components';saveArchitecture(a,component?.group?'Component grouped':'Component ungrouped');return render()}if(action==='delete-component'&&a){if(root.confirm?.('Delete this component and its connections?')){pushUndo(a);a.components=a.components.filter(x=>x.id!==id);a.connections=a.connections.filter(x=>x.sourceComponentId!==id&&x.destinationComponentId!==id);saveArchitecture(a,'Component deleted');render()}return}if(action==='undo'&&a){const stack=undoStacks.get(a.id)||[];if(!stack.length){message='Nothing to undo';return render()}const current=JSON.stringify(a),previous=JSON.parse(stack.pop());redoStacks.set(a.id,[...(redoStacks.get(a.id)||[]),current]);undoStacks.set(a.id,stack);saveArchitecture(previous,'Last architecture change undone');return render()}if(action==='redo'&&a){const stack=redoStacks.get(a.id)||[];if(!stack.length){message='Nothing to redo';return render()}const current=JSON.stringify(a),next=JSON.parse(stack.pop());undoStacks.set(a.id,[...(undoStacks.get(a.id)||[]),current]);redoStacks.set(a.id,stack);saveArchitecture(next,'Architecture change restored');return render()}if(action==='zoom-in'){zoom=Math.min(1.35,zoom+.1);return render()}if(action==='zoom-out'){zoom=Math.max(.75,zoom-.1);return render()}if(action==='fit'){zoom=1;message='Architecture fitted to the available space';return render()}if(action==='add-connection'&&a){const personal=val('ar-flow-personal'),protection=val('ar-flow-protection');if(['Yes','Possibly','Unknown'].includes(personal)&&!protection){message='Add a protection method before saving this sensitive or uncertain data flow.';return render()}return addRecord('connections',{sourceComponentId:val('ar-flow-source'),destinationComponentId:val('ar-flow-destination'),label:val('ar-flow-name')||'Data flow',dataType:val('ar-flow-name'),direction:val('ar-flow-direction'),transferMode:val('ar-flow-mode'),containsPersonalData:personal,storage:val('ar-flow-storage'),retentionPolicy:val('ar-flow-retention'),protectionMethod:protection,failureBehaviour:val('ar-flow-failure')},'Connection added')}if(action==='add-integration')return addRecord('integrations',{integrationType:val('ar-integration-type'),serviceName:val('ar-integration-name')||'Untitled integration',purpose:val('ar-integration-purpose'),dataSent:val('ar-integration-sent'),dataReceived:val('ar-integration-received'),authenticationReference:val('ar-integration-auth'),rateLimitNotes:val('ar-integration-rate'),costNotes:val('ar-integration-cost'),privacyConcerns:val('ar-integration-privacy'),failureBehaviour:val('ar-integration-failure'),fallbackBehaviour:val('ar-integration-fallback')},'Integration added');if(action==='add-failure')return addRecord('failures',{failure:val('ar-failure-name')||'Failure needs a description',detection:val('ar-failure-detection'),userMessage:val('ar-failure-message'),retry:val('ar-failure-retry'),fallback:val('ar-failure-fallback'),responsiblePerson:val('ar-failure-responsible'),recoveryProcess:val('ar-failure-recovery'),status:'Open'},'Failure plan added');if(action==='add-decision')return addRecord('decisions',{title:val('ar-decision-title')||'Untitled decision',problem:val('ar-decision-problem'),optionsConsidered:val('ar-decision-options'),selectedOption:val('ar-decision-selected'),reason:val('ar-decision-reason'),advantages:val('ar-decision-advantages'),disadvantages:val('ar-decision-disadvantages'),risks:val('ar-decision-risks'),createdBy:val('ar-decision-maker')||accountId(),decisionDate:val('ar-decision-date')||now(),reviewDate:val('ar-decision-review')},'Architecture decision added');if(action==='review'&&a){sync(a);a.issues=reviewIssues(a);a.openIssueCount=a.issues.length;a.status=a.issues.length?'Needs More Detail':'Ready for Review';saveArchitecture(a,a.issues.length?'Architecture review found issues':'Architecture is ready for human review');return render()}if(action==='resolve-issue'&&a){const issue=a.issues.find(x=>x.id===id);if(issue){issue.status='Addressed';issue.resolvedAt=now()}saveArchitecture(a,'Issue marked addressed. Review again to confirm.');return render()}if(action==='version'&&a){sync(a);preserveVersion(a);saveArchitecture(a,'Current architecture version preserved');return render()}if(action==='compare'&&a){message=a.versions.length>1?'Version comparison is available in the preserved history.':'Preserve at least two versions before comparing.';return render()}if(action==='submit'&&a){sync(a);const open=reviewIssues(a);if(open.length){a.issues=open;a.status='Needs More Detail';saveArchitecture(a,'Resolve architecture issues before requesting review');return render()}a.status='Under Review';a.submittedAt=now();preserveVersion(a);saveArchitecture(a,'Architecture submitted for authorized human review');return render()}if(action==='preview'&&a){sharePreview=true;message='Review the safe export preview. Nothing has been shared.';return render()}if(action==='close-preview'){sharePreview=false;return render()}if(action==='export-current'&&a){exportArchitecture(sync(a));return}if(action==='prototype')return root.showView?.('dataResponsibilityStudio');if(action==='listen'){const text=root.document.querySelector('#architectureContent .ar-step-content')?.innerText||'';if(root.speechSynthesis&&root.SpeechSynthesisUtterance){root.speechSynthesis.cancel();root.speechSynthesis.speak(new SpeechSynthesisUtterance(text))}else{message='Listening is not available in this browser.';render()}return}if(action==='speech'){const Recognition=root.SpeechRecognition||root.webkitSpeechRecognition,target=root.document.activeElement;if(!Recognition||!target||!['INPUT','TEXTAREA'].includes(target.tagName)){message='Select a text field first. Speech-to-Text is not available in every browser.';return render()}const recognition=new Recognition();recognition.onresult=event=>{target.value=`${target.value} ${event.results[0][0].transcript}`.trim();target.dispatchEvent(new Event('input',{bubbles:true}))};recognition.start();return}if(action==='duplicate-architecture'){const original=items.find(x=>x.id===id);if(!original)return;const copy=JSON.parse(JSON.stringify(original));copy.id=uid('architecture');copy.title=`${copy.title||'Untitled Architecture'} — Copy`;copy.status='Draft';copy.versions=[];copy.reviews=[];copy.submittedAt=copy.approvedAt=null;copy.createdAt=copy.updatedAt=now();items.unshift(copy);writeAll(items);message='Architecture duplicated';return render()}if(action==='delete-architecture'){const original=items.find(x=>x.id===id);if(!original||original.status==='Approved'){message='Approved architecture versions are preserved.';return render()}if(root.confirm?.('Delete this private architecture draft?')){writeAll(items.filter(x=>x.id!==id));message='Draft deleted';render()}return}if(action==='export'){const original=items.find(x=>x.id===id);if(original)exportArchitecture(original)}}
  function bind(){const host=root.document.getElementById('architectureContent');host?.querySelectorAll('[data-ar-template]').forEach(button=>button.addEventListener('click',()=>{const template=TEMPLATES.find(item=>item.id===button.dataset.arTemplate);if(readAll().length&&!root.confirm?.('Start a new architecture from this template? Your existing architecture will remain saved.'))return;fromTemplate(template)}));host?.querySelectorAll('[data-ar-open]').forEach(button=>button.addEventListener('click',()=>{activeId=button.dataset.arOpen;const a=getArchitecture();step=Math.min(a?.currentStep||0,9);message='Draft restored';render()}));host?.querySelectorAll('[data-ar-step]').forEach(button=>button.addEventListener('click',()=>{const a=sync(getArchitecture());saveArchitecture(a,'Draft saved');step=Number(button.dataset.arStep);render()}));host?.querySelectorAll('[data-ar-action]').forEach(button=>button.addEventListener('click',()=>handle(button.dataset.arAction,button.dataset.id)))}
  function errorView(){return `<section class="ar-error" role="alert"><h1>Project Architecture</h1><p>We could not open the Architecture workspace. Your saved project work has not been deleted.</p><div><button class="btn btn-primary" data-ar-action="retry" type="button">Try Again</button><button class="btn btn-secondary" data-ar-action="projects" type="button">Return to Projects</button><button class="btn btn-secondary" data-ar-action="projects" type="button">Select a Project</button><button class="btn btn-secondary" data-ar-action="start" type="button">Create an Architecture Manually</button></div></section>`}
  function render(){const host=root.document?.getElementById('architectureContent');if(!host)return false;readAll();host.innerHTML=loadError?errorView():(activeId&&getArchitecture()?wizard(getArchitecture()):overview());bind();host.querySelector('h1')?.focus?.();return true}
  function retry(){loadError=false;render()}
  root.ProjectArchitectureExperience=Object.freeze({STEPS,STATUSES,COMPONENT_TYPES,TEMPLATES,AI_STAGES,SECURITY_CHECKS,REVIEW_CHECK_LABELS,DATA_MODELS,render,listArchitectures:readAll,getActiveArchitecture:getArchitecture,retry,_test:{blankArchitecture,storageKey,reviewIssues}});
  if(root.document?.getElementById('aiArchitectureDesignStudioView')?.classList.contains('active'))render();
})(typeof window!=='undefined'?window:globalThis);
